from datetime import datetime


def _datediff(day1: str, day2: str) -> int:
    """Return whole calendar days day1 - day2, or 0 for absent/sentinel dates."""
    if not day1 or not day2 or day1 == "00000000" or day2 == "00000000":
        return 0

    try:
        date1 = datetime.strptime(day1, "%Y%m%d").date()
        date2 = datetime.strptime(day2, "%Y%m%d").date()
    except (TypeError, ValueError):
        return 0

    return (date1 - date2).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return workflow events for overdue live support cases."""
    events: list[dict] = []

